    {
        "defaultValue": {
            "items": [
                {
                    "field": "number",
                    "label": "Submission",
                    "refTable": "x_acme_wum_submission",
                    "type": "reference",
                    "width": "150px"
                },
                {
                    "field": "account",
                    "label": "Insured",
                    "minWidth": 160,
                    "type": "text"
                },
                {
                    "field": "line_of_business",
                    "label": "LOB",
                    "type": "text",
                    "width": "130px"
                },
