                }
            ],
            "schema": {
                "enum": [
                    "auto",
                    "manual"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Keep reference-cell links so they are clickable.",
        "fieldType": "boolean",
        "label": "Enable reference links",
        "name": "enableReferenceLinks",
        "valueType": "string"
    },
    {
        "defaultValue": "same",
        "description": "How a reference/record opens on click.",
        "fieldType": "choice",
        "label": "Reference opens in",
        "name": "referenceOpenIn",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Same tab",
                    "value": "same"
                },
                {
                    "label": "New tab",
