                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "When on, the component opens the record on click; off = only fire the Reference clicked event so the page routes.",
        "fieldType": "boolean",
        "label": "Navigate on reference click",
        "name": "navigateReferenceOnClick",
        "valueType": "string"
    },
    {
        "defaultValue": "/record/{table}/{sysId}",
        "description": "URL opened for a reference/record. Placeholders {table}/{sysId}. Use a workspace route (e.g. /x/acme/wummanager/record/{table}/{sysId}) to stay in-workspace.",
        "fieldType": "string",
        "label": "Record URL template",
        "name": "recordUrlTemplate",
        "valueType": "string"
    },
    {
        "defaultValue": "",
        "description": "Ordered group-by fields (unlimited depth) — CSV, e.g. \"line_of_business,stage\". Empty = flat list.",
        "fieldType": "string",
        "label": "Group by",
        "name": "groupBy",
        "valueType": "string"
    },
    {
        "defaultValue": "all",
        "description": "WHAT gets grouped. \"Whole result set\" scans every matching row (up to Max group rows) and builds complete groups, then pages the grouped rows in the browser — correct totals, but capped on a large table. \"Current page only\" groups just the rows of the page on screen: grouping then costs a single request, nothing is capped, and server-side paging keeps working exactly as it does for a flat list. Choose page-only for big tables where the scan is too expensive.",
        "fieldType": "choice",
        "label": "Group scope",
        "name": "groupScope",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Whole result set (scan)",
                    "value": "all"
                },
                {
                    "label": "Current page only",
                    "value": "page"
                }
            ],
            "schema": {
                "enum": [
                    "all",
                    "page"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "records",
        "description": "When grouped, how the pager works: \"records\" pages the detail rows by page size (numbered pages over the record count, group headers repeat per page — like the OOB list); \"top\" pages the top-level groups; \"off\" shows everything (scroll).",
        "fieldType": "choice",
        "label": "Group paging",
        "name": "groupPaging",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Paginate records (page size)",
                    "value": "records"
                },
                {
                    "label": "Paginate top-level groups",
                    "value": "top"
                },
                {
                    "label": "Off (show all)",
                    "value": "off"
                }
            ],
            "schema": {
                "enum": [
                    "records",
                    "top",
                    "off"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": {
            "items": []
        },
        "description": "Per-level group sort: [{ by: \"value\"|\"label\"|\"count\"|aggId, dir: \"asc\"|\"desc\" }] indexed by depth.",
        "fieldType": "json",
        "label": "Group sort",
        "name": "groupSort",
        "valueType": "string"
    },
    {
        "defaultValue": {
            "items": [
                {
                    "field": "premium",
                    "fn": "sum",
                    "format": "currency",
                    "label": "Total Premium"
                },
                {
                    "field": "premium",
                    "fn": "avg",
                    "format": "currency",
                    "label": "Avg Premium"
                }
            ]
        },
        "description": "Per-column aggregates shown on group/total rows: [{ field, fn, label?, format?, currency? }]. fn ∈ sum | avg | count | min | max. avg is weighted (exact roll-up).",
        "fieldType": "json",
        "label": "Aggregations",
        "name": "aggregations",
        "valueType": "string"
    },
    {
        "defaultValue": "client",
        "description": "client = compute over the fetched full set (default, capped by Max group rows). server = ServiceNow Aggregate API (pending enhancement; currently yields identical results via the client scan).",
        "fieldType": "choice",
        "label": "Aggregation mode",
        "name": "aggregationMode",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Client",
                    "value": "client"
                },
                {
                    "label": "Server",
                    "value": "server"
                }
            ],
            "schema": {
                "enum": [
                    "client",
                    "server"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show a Grand Total row at the bottom when grouped.",
        "fieldType": "boolean",
        "label": "Show grand total",
        "name": "showGrandTotal",
        "valueType": "string"
    },
    {
        "defaultValue": false,
        "description": "Also show a grand-total row when NOT grouped.",
        "fieldType": "boolean",
        "label": "Grand total when flat",
        "name": "grandTotalWhenFlat",
        "valueType": "string"
    },
    {
        "defaultValue": "header",
