        "label": "Show count",
        "name": "showCount",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show \"Last refreshed Xm ago\" next to the heading (Table mode, like the platform list).",
        "fieldType": "boolean",
        "label": "Show \"Last refreshed\"",
        "name": "showLastRefreshed",
        "valueType": "string"
    },
    {
        "defaultValue": "No records found.",
        "description": "Shown when the result is empty.",
        "fieldType": "string",
        "label": "Empty message",
        "name": "emptyMessage",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show the search icon in the list-controls row (expands to a box, like the platform list) — a quick text search across ALL columns of the loaded rows (client-side, works offline). In Table mode it searches the loaded page.",
        "fieldType": "boolean",
        "label": "Show search",
        "name": "showSearch",
        "valueType": "string"
    },
    {
        "defaultValue": "Search",
        "description": "Placeholder text for the search box.",
        "fieldType": "string",
        "label": "Search placeholder",
        "name": "searchPlaceholder",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show the Filter control. It toggles an inline per-column filter row whose operators + inputs adapt to each column data type: string (contains / is / starts with / …), number (=, ≠, >, <, between, …), date (on / before / after / between with date pickers), boolean (is true / false). In Table mode the active filters are ANDed into the encoded query and run SERVER-SIDE over the whole table; in Sample/JSON mode they filter the in-memory rows. A count badge shows how many filters are active; a Clear filters link resets them.",
        "fieldType": "boolean",
        "label": "Show filter",
        "name": "showFilter",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show the Sort by list control — a menu of columns; click cycles ascending → descending → clear (same as clicking a column header).",
        "fieldType": "boolean",
        "label": "Show \"Sort by\" control",
        "name": "showSortControl",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "Show the Group by list control — a MULTI-SELECT menu of columns; check several to build nested grouping interactively (badge shows the depth).",
        "fieldType": "boolean",
        "label": "Show \"Group by\" control",
        "name": "showGroupControl",
        "valueType": "string"
